import{_ as t,c as o,o as a,ae as s}from"./chunks/framework.Bi6zybwU.js";const d=JSON.parse('{"title":"Rowspan/Merge Rows","description":"Rowspan/Merge Rows","frontmatter":{"title":"Rowspan/Merge Rows","description":"Rowspan/Merge Rows"},"headers":[],"relativePath":"guide/table-formatting/rowspan.md","filePath":"guide/table-formatting/rowspan.md"}'),n={name:"guide/table-formatting/rowspan.md"};function r(i,e,l,c,g,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="rowspan-merge-rows" tabindex="-1">Rowspan/Merge Rows <a class="header-anchor" href="#rowspan-merge-rows" aria-label="Permalink to &quot;Rowspan/Merge Rows&quot;">​</a></h1><p>The <strong>Rowspan</strong> feature enables numerous cells of conjoining rows to be merged into a single row. Merge rows in a data table easily in Ninja Tables. Let&#39;s dive into this simple guide to learn how to use this feature in your table.</p><h2 id="merge-table-rows" tabindex="-1">Merge Table Rows <a class="header-anchor" href="#merge-table-rows" aria-label="Permalink to &quot;Merge Table Rows&quot;">​</a></h2><ul><li>First, go to the table where you want to apply this feature. Then go to the <strong>Custom CSS/JS</strong> option of the table.</li><li>Copy and paste the code from this <strong><a href="https://gist.github.com/reachkamrul/e8c1818cbe88daa1da9502d440b0d0c9" target="_blank" rel="noreferrer">file</a></strong> into the <strong>Custom Javascript</strong> option.</li><li>Don&#39;t forget to click on the <strong>Save Custom Javascript</strong> button. <img src="https://ninjatables.com/wp-content/uploads/2022/09/customcssJS-scaled.webp" alt=""></li><li>Now, go to the table column where you want to combine two rows and click the settings button of that column. <img src="https://ninjatables.com/wp-content/uploads/2022/09/gender-scaled.webp" alt=""> A pop-up will arrive, select the <strong>Advanced Settings</strong> and type <strong>&#39;&#39;combine&#39;&#39;</strong> into the <strong>Extra Classes</strong> field. Click the <strong>Update</strong> button to save the changes. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Combine.webp" alt=""></li><li>Now you&#39;ll see the rows containing similar data in cells will merge into one big data cell automatically. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Combine-result-scaled.webp" alt=""> This is how you can create a <strong>Rowspan</strong> in your Ninja Tables and merge table rows.</li></ul>',4)])])}const h=t(n,[["render",r]]);export{d as __pageData,h as default};
